tasks.register<Copy>("copyFileToApp") {
    // Define the source file in the root folder
    val sourceFile = file("connections.properties")  // Replace with your actual file name

    // Define the destination directory in the 'app' folder
    val destinationDir = file("app")

    // Ensure the destination directory exists, if not, create it
    doLast {
        if (!destinationDir.exists()) {
            println("Destination directory does not exist, creating: $destinationDir")
            destinationDir.mkdirs()
        }
        
        // Log source and destination for debugging
        println("Source File: $sourceFile")
        println("Destination Directory: $destinationDir")
    }

    // Ensure the file exists and then copy it
    if (sourceFile.exists()) {
        from(sourceFile)
        into(destinationDir)
    } else {
        throw GradleException("Source file does not exist: $sourceFile")
    }

    // Make sure Gradle considers the task always as not up-to-date
    outputs.upToDateWhen { false }
}

tasks.register("printTestJava") {
    group = "Verification" // Optional: Categorize the task
    description = "Prints the main java file paths from the source set."
	val testResourcesDirs = sourceSets["test"].java.srcDirs

    doLast {
        // Access the main java directory via the source set
        

        testResourcesDirs.forEach { testResourcesDir ->
            if (testResourcesDir.exists() && testResourcesDir.isDirectory) {
                println("Main Java in ${testResourcesDir.absolutePath}:")

                testResourcesDir.walkTopDown().forEach { file ->
                    if (file.isFile) {
                        println(file.relativeTo(testResourcesDir)) // Print relative paths
                    }
                }
            } else {
                println("No main java found in ${testResourcesDir.absolutePath}.")
            }
        }
    }
}

